from pathlib import Path
import json
tid='DEV-PRED-ASTRA-RESULT-NORMALIZE-R5-20261008-N1E134'
root=Path.home()/'.local/state/prediction-project-executor'
matches=[]
if root.exists():
    for p in root.rglob('*'):
        if p.is_file() and tid in p.name:
            matches.append(p)
def compact(v):
    if isinstance(v,(dict,list)): return json.dumps(v,ensure_ascii=False,separators=(',',':'))
    return str(v)
print('ERROR_CLASS=N1E134_EXECUTOR_RESULT')
out=[]
for p in sorted(matches)[:20]:
    try:
        txt=p.read_text()
        obj=json.loads(txt)
        fields={k:obj.get(k) for k in ['task_id','status','exit_code','source_commit','worktree','branch','commit','local_commit','result','error','detail','operations'] if k in obj}
        out.append(p.name+'='+compact(fields))
    except Exception:
        out.append(p.name+'='+p.read_text(errors='replace')[:1200].replace('\n',' '))
print('ERROR='+'|'.join(out)[:12000])
raise SystemExit(1)
